609	    /// 按脚本驱动的读取器：每个步骤要么返回下一段内容（长度可短于缓冲区），
610	    /// 要么返回一个错误。脚本用完后继续返回剩余内容，内容耗尽后返回 Ok(0)。
611	    /// 用于精确模拟“中断出现在任意位置”的读取序列。
612	    enum Step {
613	        /// 返回下一段内容（可为空切片以外的任意长度）。
614	        Data,
615	        /// 返回指定错误。
616	        Fail(io::ErrorKind, &'static str),
617	    }
618	
619	    struct ScriptedReader<'a> {
620	        data: &'a [u8],
621	        pos: usize,
622	        steps: &'a [Step],
623	        step_index: usize,
624	    }
625	
626	    impl<'a> ScriptedReader<'a> {
627	        fn new(data: &'a [u8], steps: &'a [Step]) -> Self {
628	            ScriptedReader { data, pos: 0, steps, step_index: 0 }
629	        }
630	    }
631	
632	    impl Read for ScriptedReader<'_> {
633	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
634	            match self.steps.get(self.step_index) {
635	                Some(Step::Data) => {
636	                    self.step_index += 1;
637	                    // 每段最多给剩余内容的一半，保证一段脚本可能对应多次内容返回，
638	                    // 且片段长度通常短于缓冲区容量。
639	                    let remaining = self.data.len() - self.pos;
640	                    let n = (remaining / 2).max(1).min(remaining).min(buf.len());
641	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
642	                    self.pos += n;
643	                    Ok(n)
644	                }
645	                Some(Step::Fail(kind, msg)) => {
646	                    self.step_index += 1;
647	                    Err(io::Error::new(*kind, *msg))
648	                }
649	                None => {
650	                    let remaining = self.data.len() - self.pos;
651	                    let n = remaining.min(buf.len());
652	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
653	                    self.pos += n;
654	                    Ok(n)
655	                }
656	            }
657	        }
658	    }
