994	    /// RFC 8410 第 4 节的 Ed25519 公钥示例（SubjectPublicKeyInfo 的 DER 编码）。
995	    const RFC8410_SPKI: &[u8] = &[
996	        0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x03, 0x21, 0x00, 0xd7, 0x5a,
997	        0x98, 0x01, 0x82, 0xb1, 0x0a, 0xb7, 0xd5, 0x4b, 0xfe, 0xd3, 0xc9, 0x64, 0x07, 0x3a,
998	        0x0e, 0xe1, 0x72, 0xf3, 0xda, 0xa6, 0x23, 0x25, 0xaf, 0x02, 0x1a, 0x68, 0xf7, 0x07,
999	        0x51, 0x1a,
1000	    ];
1001	
1002	    /// 同一示例的公钥原文（32 字节）。
1003	    const RFC8410_KEY_HEX: &str =
1004	        "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a";
1005	
1006	    /// 由算法 OID 内容字节与任意长度公钥拼装一份规范编码的 SPKI：
1007	    /// 算法参数缺省，位串未使用位数为零。这里构造的容器都很小，
1008	    /// 各层长度均以短形式单字节编码。
1009	    fn spki_der(oid_content: &[u8], key: &[u8]) -> Vec<u8> {
1010	        // 外层内容 = 算法序列（2 字节头 + 2 字节 OID 头 + OID 内容）
1011	        //          + 位串（2 字节头 + 1 字节未使用位数 + 公钥）。
1012	        let outer_len = oid_content.len() + 4 + key.len() + 3;
1013	        let mut der = vec![0x30, outer_len as u8, 0x30, (oid_content.len() + 2) as u8, 0x06];
1014	        der.push(oid_content.len() as u8);
1015	        der.extend_from_slice(oid_content);
1016	        der.push(0x03);
1017	        der.push((key.len() + 1) as u8);
1018	        der.push(0x00);
1019	        der.extend_from_slice(key);
1020	        der
1021	    }
