1082	    fn well_formed_ed448_spki_reports_unsupported_algorithm_not_malformed() {
1083	        // RFC 8410 的 Ed448 公钥：算法 1.3.101.113（OID 内容 2b 65 71），
1084	        // 参数缺省，位串未使用位数为零，公钥内容恰好 57 字节。
1085	        let der = spki_der(&[0x2b, 0x65, 0x71], &[0x44; 57]);
