1095	        assert_eq!(der, expected);
1096	
1097	        let err = Ed25519PublicKey::from_spki_der(&der).unwrap_err();
1098	        match &err {
1099	            ImportPublicKeyError::UnsupportedAlgorithm(oid) => {
1100	                assert_eq!(oid.arcs(), &[1, 3, 101, 113]);
1101	                assert_eq!(oid.to_string(), "1.3.101.113");
1102	            }
1103	            other => panic!("expected UnsupportedAlgorithm for a valid Ed448 SPKI, got {other:?}"),
1104	        }
1105	        // 提示文字要显示实际标识，并说明这个入口需要 Ed25519。
1106	        let msg = err.to_string();
1107	        assert!(msg.contains("1.3.101.113"), "message must name Ed448: {msg}");
1108	        assert!(msg.contains("1.3.101.112"), "message must name Ed25519: {msg}");
1109	        assert!(msg.to_lowercase().contains("ed25519"), "message must say Ed25519: {msg}");
1110	    }
