1370	    /// 把数值按 base-128 最短形式编码为一个 OID 子标识符，追加到 `out`。
1371	    /// 接受 u128 是为了能构造“合并前两段后超过 u64”的第一个子标识符。
1372	    fn push_subidentifier(out: &mut Vec<u8>, value: u128) {
1373	        let mut groups = [0u8; 19]; // u128 最多需要 ceil(128/7) = 19 组
1374	        let mut start = groups.len();
1375	        let mut v = value;
1376	        loop {
1377	            start -= 1;
1378	            groups[start] = (v & 0x7f) as u8;
1379	            v >>= 7;
1380	            if v == 0 {
1381	                break;
1382	            }
1383	        }
1384	        let end = groups.len() - 1;
1385	        for b in &mut groups[start..end] {
1386	            *b |= 0x80;
1387	        }
1388	        out.extend_from_slice(&groups[start..]);
1389	    }
