1391	    /// 首段为 2 的 OID 内容字节：第一个子标识符合并编码 2*40 + arc1，
1392	    /// 其余各段依次跟在后面。
1393	    fn oid_content_starting_at_2(arc1: u64, rest: &[u64]) -> Vec<u8> {
1394	        let mut content = Vec::new();
1395	        push_subidentifier(&mut content, 80 + u128::from(arc1));
1396	        for &arc in rest {
1397	            push_subidentifier(&mut content, u128::from(arc));
1398	        }
1399	        content
1400	    }
