1616	    // ----- DER 长度编码（短形式/长形式）的回归保障 -----
1617	    //
1618	    // 这一组测试只走公开入口 from_spki_der，守住一条边界：容器内容从 127
1619	    // 字节增到 128 字节、长度字段从短形式变成最短长形式时，“结构合法但
1620	    // 算法不是 Ed25519 → UnsupportedAlgorithm”与“编码损坏 → Malformed”
1621	    // 的区分不能改变。外层 SEQUENCE、算法标识所在 SEQUENCE、公钥位串三个
1622	    // 位置适用同一条规则。
1623	
1624	    /// 构造测试输入时某一层 TLV 长度字段的写法。
1625	    #[derive(Clone, Copy)]
1626	    enum LenStyle {
1627	        /// 规范最短形式：127 以内短形式，128 起最短长形式。
1628	        Canonical,
1629	        /// 长度小于 128 也写成长形式——本可用短形式，属于非规范编码。
1630	        ForcedLong,
1631	        /// 长形式数字前再补一个零字节——冗余前导零，属于非规范编码。
1632	        ForcedLongZeroPadded,
1633	    }
1634	
1635	    /// 按指定风格生成一个 DER 长度字段的字节。
1636	    fn test_len_bytes(len: usize, style: LenStyle) -> Vec<u8> {
1637	        let mut base256 = Vec::new();
1638	        let mut v = len;
1639	        loop {
1640	            base256.push((v & 0xff) as u8);
1641	            v >>= 8;
1642	            if v == 0 {
1643	                break;
1644	            }
1645	        }
1646	        base256.reverse();
1647	        match style {
1648	            LenStyle::Canonical if len < 128 => vec![len as u8],
1649	            LenStyle::Canonical | LenStyle::ForcedLong => {
1650	                let mut out = vec![0x80 | base256.len() as u8];
1651	                out.extend_from_slice(&base256);
1652	                out
1653	            }
1654	            LenStyle::ForcedLongZeroPadded => {
1655	                let mut out = vec![0x80 | (base256.len() + 1) as u8, 0x00];
1656	                out.extend_from_slice(&base256);
1657	                out
1658	            }
1659	        }
1660	    }
