1662	    /// 用指定的长度风格拼一个 TLV；内容本身原样放入。
1663	    fn test_tlv(tag: u8, content: &[u8], style: LenStyle) -> Vec<u8> {
1664	        let mut out = vec![tag];
1665	        out.extend_from_slice(&test_len_bytes(content.len(), style));
1666	        out.extend_from_slice(content);
1667	        out
1668	    }
