1670	    /// 拼装一份 SPKI：算法参数缺省、位串未使用位数为零；三层 TLV 的长度
1671	    /// 字段风格可分别指定。OID 自身始终按规范短形式编码（这些用例里 OID
1672	    /// 内容都不超过 127 字节）。
1673	    fn styled_spki(
1674	        oid_content: &[u8],
1675	        key: &[u8],
1676	        outer_style: LenStyle,
1677	        alg_style: LenStyle,
1678	        bs_style: LenStyle,
1679	    ) -> Vec<u8> {
1680	        let oid = test_tlv(TAG_OID, oid_content, LenStyle::Canonical);
1681	        let algorithm = test_tlv(TAG_SEQUENCE, &oid, alg_style);
1682	        let mut bs_content = vec![0x00];
1683	        bs_content.extend_from_slice(key);
1684	        let bit_string = test_tlv(TAG_BIT_STRING, &bs_content, bs_style);
1685	        let mut outer_content = algorithm;
1686	        outer_content.extend_from_slice(&bit_string);
1687	        test_tlv(TAG_SEQUENCE, &outer_content, outer_style)
1688	    }
