    for der in [
        RFC8410_SPKI[..30].to_vec(),
        RFC8410_SPKI.iter().copied().chain([0x00]).collect(),
    ] {
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(&pem_of_der(&der)).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }
}

