            Ed25519PublicKey::from_spki_pem(bad.as_bytes()).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }
    // 尾标记之后的任何内容：第二个块、多余空行（两个换行）、尾随文本。
    for bad in [
        format!("{block}{block}"),
        format!("{block}\n"),
        format!("{block} "),
        format!("{block}-----BEGIN PUBLIC KEY-----\n"),
    ] {
        assert_eq!(
            Ed25519PublicKey::from_spki_pem(bad.as_bytes()).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }
}

#[test]
fn pem_rejects_other_labels_and_damaged_markers() {
