        format!("-----BEGIN PUBLIC KEY-----{body}\n-----END PUBLIC KEY-----\n"),
        format!("-----BEGIN PUBLIC KEY-----\n{body}-----END PUBLIC KEY-----\n"),
        format!("-----BEGIN PUBLIC KEY----- \n{body}\n-----END PUBLIC KEY-----\n"),
